@if($points->count()>1)
@php
 $min=$points->min('price');$max=$points->max('price');$start=$points->first()->observed_at->timestamp;$span=max(1,$points->last()->observed_at->timestamp-$start);$coords=[];
 foreach($points as $p){$coords[]=(20+760*($p->observed_at->timestamp-$start)/$span).','.(180-150*($p->price-$min)/max(1,$max-$min));}
@endphp
<svg viewBox="0 0 800 210" role="img" aria-label="Evoluție preț produs; valorile și datele exacte sunt în tabelul de mai jos"><line x1="20" y1="185" x2="780" y2="185" stroke="#ccd9d0"/><polyline points="{{ implode(' ',$coords) }}" fill="none" stroke="#166953" stroke-width="3"/></svg>
