<div class="table"><table><thead><tr><th>Data schimbării</th><th>Preț produs</th><th>Livrare</th><th>Disponibilitate</th></tr></thead><tbody>@foreach($points as $p)<tr><td>{{ $p->observed_at->format('d.m.Y H:i:s') }}</td><td>{{ number_format($p->price/100,2,',','.') }} lei</td><td>{{ $p->shipping===null?'Necunoscută':number_format($p->shipping/100,2,',','.').' lei' }}</td><td>{{ $p->availability }}</td></tr>@endforeach</tbody></table></div></div>
